import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        List<String> ismlar = new ArrayList<>();
        List<String> parollar = new ArrayList<>();
        Map<String, Integer> soni = new HashMap<>();
        for (int i = 0; i < n; i++) {
            String nom = in.next();
            String parol = in.next();
            ismlar.add(nom);
            parollar.add(parol);
            soni.merge(parol, 1, Integer::sum);
        }
        int almashtirish = 0;
        for (int i = 0; i < n; i++) {
            if (soni.get(parollar.get(i)) > 1) {
                System.out.println(ismlar.get(i) + ": replace");
                almashtirish++;
            } else {
                System.out.println(ismlar.get(i) + ": ok");
            }
        }
        System.out.println("replaced: " + almashtirish);
    }
}

