#include <iostream>
#include <map>
#include <string>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<string> ismlar, parollar;
    map<string, int> soni;
    for (int i = 0; i < n; i++) {
        string nom, parol;
        cin >> nom >> parol;
        ismlar.push_back(nom);
        parollar.push_back(parol);
        soni[parol]++;
    }
    int almashtirish = 0;
    for (int i = 0; i < n; i++) {
        if (soni[parollar[i]] > 1) {
            cout << ismlar[i] << ": replace" << endl;
            almashtirish++;
        } else {
            cout << ismlar[i] << ": ok" << endl;
        }
    }
    cout << "replaced: " << almashtirish << endl;
    return 0;
}
